import{_ as t,o as l,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Developer Summit - RGW","description":"","frontmatter":{"title":"Ceph Developer Summit - RGW","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","Distributed Storage","Release Planning","Feature Development","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_RGW.md","filePath":"posts/2025/Ceph_Developer_Summit_-_RGW.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Ceph_Developer_Summit_-_RGW.md"};function r(n,e,s,g,d,u){return l(),a("div",null,[...e[0]||(e[0]=[i('<p>在本次Ceph开发者峰会中，与会者讨论了即将发布的Umbrella版本的规划与功能进展。以下为会议的关键点：</p><h3 id="关键讨论与决议" tabindex="-1">关键讨论与决议 <a class="header-anchor" href="#关键讨论与决议" aria-label="Permalink to &quot;关键讨论与决议&quot;">​</a></h3><h4 id="_1-d4n性能优化" tabindex="-1">1. D4N性能优化 <a class="header-anchor" href="#_1-d4n性能优化" aria-label="Permalink to &quot;1. D4N性能优化&quot;">​</a></h4><ul><li><strong>当前状态</strong>：Pria正在完成性能优化代码，预计将包含在Umbrella版本中。</li><li><strong>下一步计划</strong>：实现分布式缓存功能，作为下一个重要里程碑。</li><li><strong>关键词</strong>：D4N, distributed cache, performance tuning</li></ul><h4 id="_2-ddup-数据去重" tabindex="-1">2. DDUP（数据去重） <a class="header-anchor" href="#_2-ddup-数据去重" aria-label="Permalink to &quot;2. DDUP（数据去重）&quot;">​</a></h4><ul><li><strong>进展</strong>：Full DDUP PR已提交测试，Rate Limiting for DDUP的PR待文档修正后合并，Small Object DDUP逻辑开发中。</li><li><strong>功能增强</strong>：估算工具将显示常规对象和小对象的去重节省空间，帮助用户权衡性能开销。</li><li><strong>关键词</strong>：DDUP, erasure coding, deduplication, small object optimization</li></ul><h4 id="_3-快照-snapshots" tabindex="-1">3. 快照（Snapshots） <a class="header-anchor" href="#_3-快照-snapshots" aria-label="Permalink to &quot;3. 快照（Snapshots）&quot;">​</a></h4><ul><li><strong>现状</strong>：Yehuda的原实现需rebase并修复单元测试，解决QE报告的版本兼容性问题。</li><li><strong>争议</strong>：快照与bucket logging的备份方案优劣讨论，但快照仍被视为独立高价值功能。</li><li><strong>行动计划</strong>：寻找开发者接手，目标纳入Umbrella。</li><li><strong>关键词</strong>：snapshots, versioning, backup, bucket logging</li></ul><h4 id="_4-ordered-bucket-listing" tabindex="-1">4. Ordered Bucket Listing <a class="header-anchor" href="#_4-ordered-bucket-listing" aria-label="Permalink to &quot;4. Ordered Bucket Listing&quot;">​</a></h4><ul><li><strong>状态</strong>：Eric未参会，但据传开发进展较快，可能瞄准Umbrella。</li><li><strong>疑问</strong>：设计文档和代码未公开，需进一步确认优先级。</li><li><strong>关键词</strong>：Ordered Bucket Listing</li></ul><h4 id="_5-其他功能更新" tabindex="-1">5. 其他功能更新 <a class="header-anchor" href="#_5-其他功能更新" aria-label="Permalink to &quot;5. 其他功能更新&quot;">​</a></h4><ul><li><strong>Customer Managed Policies</strong>：Pritha和Raja的PR进展顺利，预计无合并障碍。</li><li><strong>Account-wide Public Access Block</strong>：已有PR，待测试和审查。</li><li><strong>AWS Organization APIs</strong>：初期设计阶段，目标支持账户层级管理和配额控制，但Umbrella版本可能来不及纳入。</li><li><strong>S3 Vectors</strong>：处于设计阶段，明确排除在Umbrella外。</li><li><strong>Log Offload</strong>：确定延迟至V版本合并。</li><li><strong>关键词</strong>：Customer Managed Policies, Account-wide Public Access Block, AWS Organization APIs, S3 Vectors, Log Offload</li></ul><h4 id="_6-技术债务与弃用" tabindex="-1">6. 技术债务与弃用 <a class="header-anchor" href="#_6-技术债务与弃用" aria-label="Permalink to &quot;6. 技术债务与弃用&quot;">​</a></h4><ul><li><strong>OMAP Data Logs</strong>：计划在Umbrella版本中标记为deprecated，但实际移除推迟至后续版本。</li><li><strong>关键词</strong>：deprecation, OMAP, migration</li></ul><h4 id="_7-bucket-logging-增强" tabindex="-1">7. Bucket Logging 增强 <a class="header-anchor" href="#_7-bucket-logging-增强" aria-label="Permalink to &quot;7. Bucket Logging 增强&quot;">​</a></h4><ul><li><strong>EC Pool 支持</strong>：NIT正在开发异步刷新临时日志的功能，设计改动较大，但预计纳入Umbrella。</li><li><strong>关键词</strong>：bucket logging, EC pools, asynchronous flush</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ol><li>合并D4N性能优化代码，启动分布式缓存开发。</li><li>加速DDUP PR合并，完成Small Object DDUP。</li><li>分配开发者解决快照测试和版本兼容性问题。</li><li>通过邮件公开功能列表，收集社区反馈。</li><li>继续使用EtherPad记录进展。</li></ol><p>本次会议还讨论了Tentacle RC1的发布情况，以及社区成员对于即将到来的版本的兴趣和需求。</p>',19)])])}const _=t(o,[["render",r]]);export{h as __pageData,_ as default};
